import 'package:pingo_mobile/features/home/domain/reminder_item.dart';

enum ChatMessageSender {
  user,
  pingo,
}

enum ChatMessageType {
  text,
  memoryReminder,
  documentNote,
}

/// Payload representing a structured documentation or note generated by Pingo.
class DocumentPayload {
  final String title;
  final String category;
  final String summary;
  final List<String> bulletPoints;
  final List<String> tags;

  const DocumentPayload({
    required this.title,
    required this.category,
    required this.summary,
    this.bulletPoints = const [],
    this.tags = const [],
  });
}

/// A polymorphic conversational chat message.
class ChatMessage {
  final String id;
  final String text;
  final ChatMessageSender sender;
  final ChatMessageType type;
  final ReminderItem? reminder;
  final DocumentPayload? document;
  final DateTime timestamp;

  const ChatMessage({
    required this.id,
    required this.text,
    required this.sender,
    this.type = ChatMessageType.text,
    this.reminder,
    this.document,
    required this.timestamp,
  });

  ChatMessage copyWith({
    String? id,
    String? text,
    ChatMessageSender? sender,
    ChatMessageType? type,
    ReminderItem? reminder,
    DocumentPayload? document,
    DateTime? timestamp,
  }) {
    return ChatMessage(
      id: id ?? this.id,
      text: text ?? this.text,
      sender: sender ?? this.sender,
      type: type ?? this.type,
      reminder: reminder ?? this.reminder,
      document: document ?? this.document,
      timestamp: timestamp ?? this.timestamp,
    );
  }
}

